def group_pairs(pairs):
    out = {}
    for k, v in pairs:
        out.setdefault(k, []).append(v)
    return out

def run_length(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))
        i = j
    return ''.join(out)

